<script setup>
import {ref,computed,nextTick} from 'vue'
import Icon from '../Icon.vue'
import SocialLinks from './SocialLinks.vue'
import ProfileEditor from './ProfileEditor.vue'
import ProviderCatalogue from './ProviderCatalogue.vue'
import FollowUpdates from './FollowUpdates.vue'
import {community,approveProfile,relationship,changeLink} from './community'
import {isDemo,call} from '../service'
import {previewMode} from '../preview/mode'
const props=defineProps({member:Object,marketplace:Object}),emit=defineEmits(['navigate','notify','refresh'])
const db=ref(isDemo?community():{profiles:[],pending:[],links:[]}),editingProfile=ref(false),query=ref(''),selected=ref(null),message=ref(''),joinType=ref(''),shared=ref(''),nativeFollowers=ref(0),nativeOwns=ref(false),catalogue=ref({classes:[],teachers:[]}),catalogueBusy=ref(false)
const directoryRoot=ref(null),parentInstitute=ref(null),directoryKind=ref('All')
function openTeacher(teacher){if(selected.value?.kind==='Institute')parentInstitute.value=selected.value;view(teacher)}
function backToInstitute(){const institute=parentInstitute.value;parentInstitute.value=null;if(institute)view(institute)}
const identity=computed(()=>isDemo?props.member.name:props.member.user)
const owner=computed(()=>props.member.role==='PlatformAdmin'),profiles=computed(()=>db.value.profiles.filter(p=>p.kind!=='Student'&&(directoryKind.value==='All'||p.kind===directoryKind.value)&&(p.username+' '+p.display_name+' '+p.subjects).toLowerCase().includes(query.value.toLowerCase().replace(/^@/,''))))
const followers=p=>db.value.links.filter(l=>l.profile===p.name&&l.kind==='Follow'&&l.status==='Active').length
const mine=(p,kind)=>db.value.links.find(l=>l.profile===p.name&&l.user===identity.value&&l.kind===kind)
const classList=computed(()=>!isDemo?catalogue.value.classes:(props.marketplace?.classes||[]).filter(c=>c.provider===selected.value?.name||selected.value?.kind==='Teacher'&&c.teacher===selected.value?.display_name))
const affiliateTeachers=computed(()=>{const ids=new Set((props.marketplace?.classes||[]).filter(c=>c.provider===selected.value?.name).map(c=>c.teacher));return [...ids]})
const owns=p=>!isDemo?nativeOwns.value:p.user===identity.value||p.owner===identity.value||(props.member.role==='Admin'&&p.name==='teen-academy')
async function load(){if(isDemo){db.value=community();return}try{const p=await call(owner.value?'pending':'search',{query:query.value},'profiles');if(owner.value)db.value.pending=p;else db.value.profiles=p}catch(e){message.value=e.message}}
let viewRequest=0
async function view(p){const request=++viewRequest;message.value='';cataloguePage.value=0;selected.value=p;shared.value='';catalogue.value={classes:[],teachers:[]};catalogueBusy.value=true;if(!isDemo){try{const [r,c]=await Promise.all([call('relationships',{profile:p.name},'profiles'),call('detail',{profile:p.name},'catalog')]);if(request!==viewRequest)return;nativeFollowers.value=r.followers;nativeOwns.value=r.owns_profile;db.value.links=r.relationships;catalogue.value=c;selected.value={...p,...c.profile}}catch(e){message.value=e.message}}catalogueBusy.value=false;await nextTick();directoryRoot.value?.scrollIntoView({block:'start'})}
async function follow(p){try{const l=mine(p,'Follow');if(l?.status==='Active'){if(isDemo)changeLink(l.name,'Left');else await call('change_relationship',{relationship:l.name,status:'Left'},'profiles')}else if(isDemo)relationship(p.name,props.member.name,'Follow');else await call('relate',{profile:p.name,kind:'Follow'},'profiles');await load();if(!isDemo)await view(p);message.value='Follow preference updated. Following gives news updates; it does not unlock paid classes.'}catch(e){message.value=e.message}}
async function join(p){try{const kind=props.member.role==='Teacher'?'Teacher membership':'Student join';if(isDemo)relationship(p.name,props.member.name,kind);else await call('relate',{profile:p.name,kind},'profiles');await load();if(!isDemo)await view(p);message.value='Request sent. The provider will review your membership.'}catch(e){message.value=e.message}}
async function review(p,status){try{if(isDemo)approveProfile(p.name,status);else await call('review',{profile:p.name,decision:status,reason:'Reviewed by platform owner'},'profiles');await load();message.value=status==='Verified'?'Verified badge and unique code issued.':'Profile request rejected.'}catch(e){message.value=e.message}}
async function update(l,status){try{if(isDemo)changeLink(l.name,status);else await call('change_relationship',{relationship:l.name,status},'profiles');await load();if(!isDemo&&selected.value)await view(selected.value)}catch(e){message.value=e.message}}
async function copyId(p){shared.value=p.lms_id||p.code||'';try{await navigator.clipboard.writeText(shared.value);message.value='LMS ID copied.'}catch{message.value='Your LMS ID is shown below. Select it to copy.'}}

const enrolling=ref(false)
const cataloguePage=ref(0)
async function moreClasses(){if(catalogueBusy.value)return;catalogueBusy.value=true;try{const page=cataloguePage.value+1;const c=await call('detail',{profile:selected.value.name,page},'catalog');catalogue.value={...catalogue.value,classes:[...catalogue.value.classes,...c.classes],teachers:[...catalogue.value.teachers,...c.teachers],has_more:c.has_more};cataloguePage.value=page}catch(e){message.value=e.message}finally{catalogueBusy.value=false}}
async function enroll(c){if(enrolling.value)return;enrolling.value=true;try{if(c.programme){emit('navigate','programmes');return}if(c.enrolled){emit('navigate','classrooms');return}const result=!isDemo?await call('join_class',{classroom:c.name},'catalog'):await call('marketplace_enroll',{classroom:c.name});c.enrolled=true;emit('refresh');message.value=result?.existing?'You are already enrolled. Open My classrooms or Class fees to continue.':c.fee_mode==='Free'?'You have joined this free class. Open My classrooms to start learning.':'Class enrollment created. Open Class fees to complete payment; no money has been charged.'}catch(e){message.value=e.message}finally{enrolling.value=false}}
load().then(async()=>{const username=new URLSearchParams(location.search).get('profile');if(username){let p=db.value.profiles.find(p=>p.username===username);if(!p){try{p=(await call('search',{query:username},'profiles')).find(p=>p.username===username)}catch{}}if(p)view(p)}})
</script>
<template><section ref="directoryRoot" class="connections-page"><div v-if="!selected||owner" class="page-heading"><div><span class="eyebrow">GOOD PEOPLE. MEANINGFUL CONNECTIONS.</span><h1>{{owner?'A little trust goes a long way.':'Find your learning people.'}}</h1><p>{{owner?'Review provider profiles and issue their verified identity.':'Find a username, follow their news, or request to join their learning community.'}}</p></div><button v-if="member.role==='Teacher'||member.role==='Admin'" class="button primary" @click="editingProfile=!editingProfile">My profile <Icon name="Pencil" :size="16"/></button></div><p v-if="message" class="form-note" role="status">{{message}}</p><ProfileEditor v-if="editingProfile" :member="member" @navigate="emit('navigate',$event)" @saved="editingProfile=false;load()"/><template v-if="owner"><section class="panel review-providers"><h2>Provider verification requests</h2><article v-for="p in db.pending.filter(p=>p.status==='Pending')" class="connection-row"><div><h3>{{p.display_name}}</h3><p>@{{p.username}} · {{p.kind}} · {{p.country}}</p></div><button class="button primary" @click="review(p,'Verified')">Verify & issue code</button><button class="button subtle" @click="review(p,'Rejected')">Reject</button></article><p v-if="!db.pending.some(p=>p.status==='Pending')">No provider profiles waiting for approval.</p><p class="field-help">{{isDemo?'These are fictional preview approvals.':'Review business/teacher evidence before issuing verification.'}}</p></section></template><template v-else><label v-if="!selected" class="search connection-search"><Icon name="Search"/><input v-model="query" @input="!isDemo&&load()" placeholder="Find @username, institute or teacher" aria-label="Find profiles"></label><template v-if="!selected"><div class="directory-kind-tabs" aria-label="Profile types"><button v-for="kind in ['All','Institute','Teacher']" :key="kind" class="button subtle" :aria-pressed="directoryKind===kind" @click="directoryKind=kind">{{kind==='All'?'Everyone':kind==='Institute'?'Institutes':'Teachers'}}</button></div><div v-if="!profiles.length" class="panel directory-empty"><Icon name="Sprout" :size="32"/><h2>A little space for good people.</h2><p>{{query?'No verified profiles match your search. Try a name or username.':'Verified teachers and institutes will appear here when their profiles are approved.'}}</p></div><div class="connection-grid"><article v-for="p in profiles" class="panel connection-card"><img v-if="p.cover_image" class="directory-cover" :src="p.cover_image" alt="" loading="lazy"><div class="connection-avatar"><img v-if="p.profile_image" :src="p.profile_image" alt="" loading="lazy"><span v-else>{{p.display_name.slice(0,1)}}</span></div><small v-if="p.lms_id" class="directory-lms-id">{{p.lms_id}}</small><span class="badge violet">{{p.kind}}</span><h2>{{p.display_name}}</h2><p>@{{p.username}}</p><SocialLinks :profile="p"/><span class="connection-verification"><Icon name="BadgeCheck" :size="16"/>{{p.code}} · {{isDemo?'Demo verified':'Verified'}}</span><p>{{followers(p)}} followers · {{p.country}}</p><button class="button primary" @click="view(p)">View profile <Icon name="ArrowRight" :size="16"/></button></article></div></template><template v-else><nav class="provider-breadcrumb" aria-label="Profile navigation"><button class="text-button" @click="selected=null;parentInstitute=null">Teachers & institutes</button><template v-if="parentInstitute"><Icon name="ChevronRight" :size="14"/><button class="text-button" @click="backToInstitute">{{parentInstitute.display_name}}</button></template><Icon name="ChevronRight" :size="14"/><span>{{selected.display_name}}</span></nav><div class="directory-hero-cover" :class="{empty:!selected.cover_image}"><img v-if="selected.cover_image" :src="selected.cover_image" alt="Profile cover"></div><section class="connection-hero"><div class="provider-identity-photo"><div class="connection-avatar big"><img v-if="selected.profile_image" :src="selected.profile_image" alt="Profile picture"><span v-else>{{selected.display_name.slice(0,1)}}</span></div><small v-if="selected.lms_id" class="directory-lms-id">{{selected.lms_id}}</small></div><div><span class="eyebrow">{{selected.kind==='Teacher'?'MEET YOUR TEACHER':'YOUR LEARNING COMMUNITY'}}</span><h1>{{selected.display_name}}</h1><p>{{selected.tagline}}</p><p>@{{selected.username}} · {{selected.country}}</p><p v-if="selected.qualifications">{{selected.qualifications}}</p><div class="inline wrap"><span class="badge violet"><Icon name="BadgeCheck" :size="16"/>{{selected.code}} · {{isDemo?'Demo verified':'Verified'}}</span><span>{{isDemo?followers(selected):nativeFollowers}} followers</span><span>{{catalogue.class_count??classList.length}} published classes</span></div></div><div class="connection-hero-actions"><SocialLinks :profile="selected" :show-empty="true"/><button class="button subtle" @click="follow(selected)">{{mine(selected,'Follow')?.status==='Active'?'Following ✓':'Follow updates'}}</button><button v-if="['Student','Teacher'].includes(member.role)" class="button primary" :disabled="['Active','Pending'].includes(mine(selected,member.role==='Teacher'?'Teacher membership':'Student join')?.status)" @click="join(selected)">{{mine(selected,member.role==='Teacher'?'Teacher membership':'Student join')?.status||'Request to join'}}</button><button class="text-button" @click="copyId(selected)"><Icon name="Copy" :size="15"/>Copy ID</button></div></section><input v-if="shared" readonly :value="shared" aria-label="LMS ID to copy" class="shared-profile"><div class="connection-details"><details class="provider-about"><summary>About {{selected.kind==='Institute'?'our institute':'this teacher'}}</summary><section class="panel"><h2>About {{selected.kind==='Teacher'?'me':'our community'}}</h2><p>{{selected.bio}}</p><dl><dt>Subjects & curriculum</dt><dd>{{selected.subjects||selected.curriculum||selected.education_system}}</dd><dt>Grades / levels</dt><dd>{{selected.grades||'See each class'}}</dd><dt>Teaching languages</dt><dd>{{selected.languages}}</dd></dl><h3 v-if="selected.kind==='Teacher'">Institute memberships</h3><p v-if="selected.kind==='Teacher'">Independent teaching and approved institute memberships can coexist. Earnings follow the owner of each class.</p><article v-for="l in db.links.filter(l=>l.user===identity&&l.kind==='Teacher membership'&&['Active','Pending'].includes(l.status))" class="connection-row"><span>{{db.profiles.find(p=>p.name===l.profile)?.display_name}} · {{l.status}}</span><button class="text-button" @click="update(l,'Left')">Leave institute</button></article></section></details><ProviderCatalogue :profile="selected" :catalogue="catalogue" :member="member" :busy="catalogueBusy" :enrolling="enrolling" @teacher="openTeacher" @enroll="enroll" @more="moreClasses"/><div v-if="message" class="catalogue-feedback" role="status"><p>{{message}}</p><button class="button subtle" @click="emit('navigate','classrooms')">My classrooms</button><button v-if="member.role==='Student'" class="button primary" @click="emit('navigate','payments')">Class fees</button></div></div><FollowUpdates v-if="owns(selected)" :member="member" :profile="selected"/><section v-if="owns(selected)" class="panel review-providers"><h2>Membership requests & people</h2><article v-for="l in db.links.filter(l=>l.profile===selected.name&&l.kind!=='Follow'&&['Pending','Active'].includes(l.status))" class="connection-row"><span>{{l.user}} · {{l.kind}} · {{l.status}}</span><button v-if="l.status==='Pending'" class="button primary" @click="update(l,'Active')">Approve request</button><button class="button subtle" @click="update(l,l.status==='Active'?'Removed':'Rejected')">{{l.status==='Active'?'Remove membership':'Reject request'}}</button></article><p>Students register themselves. Share your profile to invite them to follow or request membership.</p></section></template></template></section></template>
<style>.connection-search{max-width:580px;margin:25px 0}.connection-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:23px}.connection-card{padding:28px;border-radius:27px!important;display:flex;flex-direction:column;gap:15px}.connection-card h2{font-size:20px}.connection-card p{font-size:12px}.connection-avatar{width:57px;height:60px;display:grid;place-items:center;border-radius:21px;background:linear-gradient(135deg,rgb(108 106 238 / 12%),#6C6AEE);font-size:23px;color:#5f4288;box-shadow:0 6px 16px #6C6AEE18}.connection-avatar.big{width:100px;height:108px;font-size:40px}.connection-verification{display:flex;align-items:center;gap:8px;font-size:11px;color:#6C6AEE}.connection-hero{display:flex;gap:25px;align-items:center;padding:38px;margin:25px 0;border-radius:30px;background:linear-gradient(120deg,#6C6AEE8c,#6C6AEE22)}.connection-hero h1{font-size:31px;margin:15px 0}.connection-hero .inline{margin-top:20px;font-size:12px}.connection-hero-actions{display:flex;flex-direction:column;gap:12px;margin-inline-start:auto}.connection-details{display:grid;grid-template-columns:.8fr 1.2fr;gap:25px}.connection-details>.panel{padding:28px;align-self:start}.connection-details h2{margin-bottom:23px}.connection-details p{font-size:13px;line-height:1.9}.connection-details dl{display:grid;grid-template-columns:1fr 1.4fr;gap:16px;font-size:12px;margin:24px 0}.connection-details dd{margin:0}.connection-class{padding:25px;margin:20px 0}.connection-class h3{font-size:21px;margin:18px 0}.connection-class strong{display:block;margin:20px 0;font-size:13px}.connection-row{display:flex;gap:18px;align-items:center;flex-wrap:wrap;padding:22px 0;border-bottom:1px solid var(--student-border)}.connection-row>div{flex:1}.review-providers{padding:30px;margin-top:25px}.shared-profile{width:100%;padding:16px;border-radius:12px;border:1px solid var(--student-border);background:var(--student-card);color:var(--student-ink);margin-bottom:25px}.teacher-mini-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}.teacher-mini-grid>article{padding:22px}.teacher-mini-grid h3{margin:17px 0}@media(max-width:1000px){.connection-grid{grid-template-columns:repeat(2,1fr)}.connection-hero{flex-wrap:wrap}.connection-details{grid-template-columns:1fr}}@media(max-width:600px){.connection-grid{grid-template-columns:1fr}.connection-hero{padding:24px}.connection-hero-actions{margin:0;width:100%}.teacher-mini-grid{grid-template-columns:1fr}}</style>

<style>.directory-cover{width:100%;aspect-ratio:8/3;object-fit:cover;border-radius:16px;margin-bottom:18px}.connection-avatar img{width:100%;height:100%;border-radius:inherit;object-fit:cover}.directory-hero-cover{width:100%;aspect-ratio:8/3;max-height:350px;background:linear-gradient(125deg,rgb(108 106 238 / 8%),rgb(108 106 238 / 18%));border-radius:26px 26px 0 0;margin-top:24px;overflow:hidden}.directory-hero-cover img{width:100%;height:100%;object-fit:cover}.provider-header-socials+.connection-hero{border-radius:0 0 26px 26px;margin-top:0}.provider-header-socials+.connection-hero .big{border:5px solid var(--student-card,#fff);margin-top:-60px;position:relative;box-shadow:0 8px 20px #6e4a8820}</style>

<style>.directory-empty{padding:48px 28px;text-align:center}.directory-empty h2{font-size:21px;margin:20px 0 12px}.directory-empty p{font-size:13px;line-height:1.8;color:var(--student-muted)}</style>

<style>.provider-header-socials{display:flex;justify-content:flex-end;background:var(--student-card,#fff);padding:12px 24px;min-height:68px}.teacher-mini-grid .provider-social-links{margin:12px 0}.provider-header-socials+.connection-hero .big{margin-top:-110px}@media(max-width:600px){.provider-header-socials{padding-left:135px;padding-right:16px}.provider-header-socials+.connection-hero .big{margin-top:-65px}}</style>

<style>.directory-lms-id{display:block;color:var(--brand,#63339a);font-size:10px;font-weight:700;letter-spacing:.5px;margin:9px 0 15px}.connection-hero{flex-wrap:wrap}.connection-hero>.directory-lms-id{flex-basis:100%;order:3;margin:0}</style>

<style>.provider-identity-photo{flex-shrink:0;text-align:center}.provider-identity-photo .connection-avatar{margin-inline:auto}.provider-identity-photo .directory-lms-id{margin-bottom:0}</style>

<style>.connections-page .connection-details{display:block}.provider-about{border:1px solid var(--student-border,#e8e0ef);border-radius:15px;margin-top:25px;overflow:hidden}.provider-about summary{padding:17px 22px;cursor:pointer;font-size:13px;font-weight:600}.provider-about>.panel{border:0;box-shadow:none;padding:0 22px 22px;margin:0}.provider-breadcrumb{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-top:20px;font-size:12px;color:var(--student-muted,#817489)}.provider-breadcrumb .text-button{font-size:12px}.provider-breadcrumb>span{font-weight:600}.directory-kind-tabs{display:flex;gap:10px;margin-bottom:24px}.directory-kind-tabs button[aria-pressed=true]{background:var(--brand,#6128a5);color:white}.connections-page .connection-hero{background:var(--student-card,#fff);border:1px solid var(--student-border,#e8e0ef);border-top:0;padding:20px 28px 28px;align-items:flex-start;gap:24px}.connections-page .directory-hero-cover{aspect-ratio:4/1;max-height:280px}.connections-page .connection-hero h1{font-size:30px;letter-spacing:-.8px}.connections-page .connection-hero .big{border-radius:50%;width:100px;height:100px;margin-top:-78px}.connections-page .provider-header-socials{border-inline:1px solid var(--student-border,#e8e0ef);padding:10px 24px;min-height:62px}.connections-page .connection-hero-actions{padding-top:14px}.catalogue-feedback{margin-top:22px;background:var(--student-card,#fff);border:1px solid var(--student-border,#e8e0ef);padding:20px;border-radius:16px}.catalogue-feedback p{font-size:13px;margin-bottom:12px}.catalogue-feedback button{margin-right:10px}@media(max-width:650px){.connections-page .directory-hero-cover{aspect-ratio:2.6/1}.connections-page .connection-hero{padding:16px 20px 24px}.connections-page .connection-hero h1{font-size:25px}.connections-page .provider-header-socials{padding-left:130px}.connections-page .connection-hero .big{width:85px;height:85px;margin-top:-75px}.connections-page .connection-hero-actions{flex-direction:row;flex-wrap:wrap}}
</style>

<style>.connections-page{scroll-margin-top:85px}.provider-breadcrumb{flex-direction:row!important;justify-content:flex-start!important}.provider-breadcrumb>button{width:auto!important}.provider-breadcrumb>span{flex:0 1 auto}.provider-breadcrumb>svg{flex-shrink:0}</style>

<style>
.connections-page .connection-hero{display:grid;grid-template-columns:120px minmax(0,1fr) 210px;align-items:start;gap:26px;margin:0 0 24px;border-radius:0 0 26px 26px;padding:30px;background:var(--student-card,#fff)}
.connections-page .connection-hero .big{margin:0 auto;width:108px;height:108px;border:5px solid var(--student-card,#fff);border-radius:50%}
.connections-page .connection-hero h1{margin:10px 0 14px;font-size:clamp(24px,2.5vw,34px);line-height:1.18}
.connections-page .connection-hero p{font-size:14px;line-height:1.65;margin:3px 0;color:var(--student-muted,#71697a)}
.connections-page .connection-hero-actions{padding:0;margin:0;gap:10px;width:100%;align-items:stretch}
.connection-hero-actions .provider-social-links{justify-content:flex-end;flex-wrap:wrap;margin:0 0 12px;gap:5px}
.connection-hero-actions .provider-social-links :is(a,button){width:30px;height:30px;padding:6px;border-radius:9px}
.connection-hero-actions>.text-button{justify-content:center;padding:10px}
.connections-page .connection-hero .inline{gap:10px;line-height:1.6;margin-top:20px}
@media(max-width:1000px){.connections-page .connection-hero{grid-template-columns:100px minmax(0,1fr);gap:20px;padding:24px}.connections-page .connection-hero .big{width:90px;height:90px}.connections-page .connection-hero-actions{grid-column:1/-1;display:flex;flex-direction:row;flex-wrap:wrap;align-items:center}.connection-hero-actions .provider-social-links{margin:0 auto 0 0}.connection-hero-actions>.button{padding:10px 14px}}
@media(max-width:560px){.connections-page .connection-hero{grid-template-columns:1fr;text-align:center}.connections-page .connection-hero .inline{justify-content:center}.connections-page .connection-hero-actions{justify-content:center}.connection-hero-actions .provider-social-links{flex-basis:100%;justify-content:center;margin:0 0 8px}.connections-page .directory-hero-cover{margin-top:16px}}
</style>
